namespace Flow {
    const int N = 50*T + 2;
    const int M = 2*N*C + N + 7;
    int par[N], first[N], nxt[2*M], ep[2*M], m;
    ll flo[2*M], cap[2*M], cost[2*M];

    void init() {
        m = 0;
        memset(first, -1, sizeof first);
        memset(flo, 0, sizeof flo);
    }

    void add_edge(int a, int b, ll c = 1, ll p = 0) {
        nxt[m] = first[ep[m] = a]; first[ep[m]] = m; cap[m] = c; cost[m] = p; ++m;
        nxt[m] = first[ep[m] = b]; first[ep[m]] = m; cap[m] = 0; cost[m] = -p; ++m;
    }

    bool vis[N];
    ll pot[N], dist[N];
    int q[N], inq[N];

    void mcf_pot_init(int n) {
        memset(pot, 0, sizeof pot);
        // all edge costs >= 0, so potentials stay zero
    }

    ll mcf_update(int s, int t, ll& price, int n) {
        memset(vis, 0, sizeof vis);
        fill(dist, dist + n, INF);
        dist[s] = 0;
        memset(inq, -1, sizeof inq);
        int qs = 0;
        inq[q[qs++] = s] = 0;
        while (qs) {
            int u = q[0];
            inq[u] = -1;
            q[0] = q[--qs];
            if (qs) inq[q[0]] = 0;
            for (int i = 0, j = 2*i + 1, t; j < qs; i = j, j = 2*i + 1) {
                if (j + 1 < qs && dist[q[j+1]] < dist[q[j]]) ++j;
                if (dist[q[j]] >= dist[q[i]]) break;
                int tmp = q[i]; q[i] = q[j]; q[j] = tmp;
                tmp = inq[q[i]]; inq[q[i]] = inq[q[j]]; inq[q[j]] = tmp;
            }
            if (vis[u]) continue;
            vis[u] = 1;
            for (int e = first[u]; e != -1; e = nxt[e]) {
                int v = ep[e^1];
                if (flo[e] < cap[e] && dist[v] > dist[u] + pot[u] - pot[v] + cost[e]) {
                    dist[v] = dist[u] + pot[u] - pot[v] + cost[e];
                    par[v] = e;
                    if (inq[v] < 0) {
                        inq[q[qs] = v] = qs;
                        qs++;
                    }
                    for (int i = inq[v], j = (i-1)/2, t; dist[q[i]] < dist[q[j]]; i = j, j = (i-1)/2) {
                        int tmp = q[i]; q[i] = q[j]; q[j] = tmp;
                        tmp = inq[q[i]]; inq[q[i]] = inq[q[j]]; inq[q[j]] = tmp;
                    }
                }
            }
        }
        if (dist[t] >= INF) return 0;
        ll df = INF;
        for (int e, i = t; i != s; i = ep[e]) {
            e = par[i];
            df = min(df, cap[e] - flo[e]);
