                        dist[v] = dist[u] + pot[u] - pot[v] + cost[e];
                        par[v] = e;
                        if (inq[v] < 0) {
                            inq[q[qs] = v] = qs;
                            qs++;
                        }
                        // sift up from current position
                        for (int i = inq[v], j = (i - 1) / 2; dist[q[i]] < dist[q[j]]; i = j, j = (i - 1) / 2) {
                            int tmp = q[i];
                            q[i] = q[j];
                            q[j] = tmp;
                            tmp = inq[q[i]];
                            inq[q[i]] = inq[q[j]];
                            inq[q[j]] = tmp;
                        }
                    }
                }
            }
            if (dist[t] >= INF) return 0;
            long df = INF;
            for (int e, i = t; i != s; i = ep[e]) {
                e = par[i];
                df = Math.min(df, cap[e] - flo[e]);
            }
            for (int e, i = t; i != s; i = ep[e]) {
                e = par[i];
            flo[e] += df;
            flo[e ^ 1] -= df;
            price[0] += df * cost[e];
            }
            for (int i = 0; i < n; ++i) pot[i] = Math.min(INF, dist[i] + pot[i]);
            return df;
        }
